Example C program:
#include <stdio.h>
#include <unistd.h>
#include <sys/utsname.h>

int main() {
    struct utsname info;
    printf("PID: %d\n", getpid());

    if (uname(&info) == 0) {
        printf("System: %s\n", info.sysname);
        printf("Release: %s\n", info.release);
        printf("Machine: %s\n", info.machine);
    }
    return 0;
}

